<script lang="ts">
  import { onDestroy } from 'svelte'; import { goto } from '$app/navigation'; import { user, userReady } from '$lib/stores/user';
  import { SURGERY_BLOCKS, SURGERY_SYLLABUS } from '$lib/study/surgerySyllabus';
  import { createEmptySurgeryState, type SessionSnapshot, type SurgeryState } from '$lib/study/surgerySchema';
  import { baselineCandidates, createDefaultStudyPlan, createPlanProgress, type StudyPlanConfig, type StudyPlanProgress, type PlanPass } from '$lib/study/studyPlanSchema';
  import { buildSchedule, dateKey, forecast, pacing, passCount, phaseForDate, shortReviewsDue } from '$lib/study/studyPlanEngine';
  import { saveStudyPlan, saveStudyPlanProgress, subscribeToStudyPlan, subscribeToSurgerySessions, subscribeToSurgeryState } from '$lib/study/surgeryRepository';
  let state:SurgeryState=createEmptySurgeryState(), sessions:SessionSnapshot[]=[], config:StudyPlanConfig|null=null, progress:StudyPlanProgress|null=null, loading=true, error='', notice='', tab='overview', baseline=new Set<string>(), uid='', unsubs:(()=>void)[]=[];
  $: currentUid=$user?.uid as string|undefined;
  $: if($userReady&&currentUid&&currentUid!==uid) subscribe(currentUid);
  $: today=dateKey();
  $: phase=config?phaseForDate(config,today):undefined;
  $: currentPacing=config&&progress&&phase&&phase.type!=='buffer'?pacing(config,progress,phase,today):null;
  $: first=progress?passCount(progress,'first'):0;
  $: second=progress?passCount(progress,'second'):0;
  $: daysLeft=config?Math.max(0,Math.ceil((new Date(config.examDate+'T12:00:00').getTime()-new Date(today+'T12:00:00').getTime())/86400000)):0;
  $: due=progress?shortReviewsDue(progress,today):[];
  $: candidates=baselineCandidates(state);
  $: projection=config&&progress&&phase&&phase.type!=='buffer'?forecast(config,progress,phase,today):null;
  $: schedule=config&&progress&&phase&&phase.type!=='buffer'?buildSchedule(config,progress,phase):[];
  $: todaySessions=sessions.filter(s=>s.date.slice(0,10)===today);
  $: topicsAssessedToday=new Set(todaySessions.flatMap(s=>s.topicIds??[])).size;
  $: questionsToday=todaySessions.reduce((sum,s)=>sum+s.questions,0);
  function subscribe(id:string){unsubs.forEach(f=>f());uid=id;loading=true;unsubs=[subscribeToSurgeryState(id,v=>{state=v;loading=false},fail),subscribeToSurgerySessions(id,v=>sessions=v,fail),subscribeToStudyPlan(id,(c,p)=>{config=c;progress=p;loading=false},fail)];}
  function fail(e:unknown){error=e instanceof Error?e.message:'Something went wrong';loading=false} onDestroy(()=>unsubs.forEach(f=>f()));
  async function activate(){if(!uid)return; const c=createDefaultStudyPlan(),p=createPlanProgress(state,[...baseline]); await saveStudyPlan(uid,c,p);notice=`Plan activated with ${p.baselineFirstPassCount} previously covered topics.`;}
  async function saveProgress(p:StudyPlanProgress){if(!uid)return;p.updatedAt=new Date().toISOString();await saveStudyPlanProgress(uid,p);progress=p;}
  async function togglePass(id:string,pass:PlanPass){if(!progress)return;const p=structuredClone(progress),t=p.topics[id]??{};const key=pass==='first'?'firstPassCompletedAt':'secondPassCompletedAt',sourceKey=pass==='first'?'firstPassSource':'secondPassSource',manual=pass==='first'?'firstPassManual':'secondPassManual',previous=t[key],changedAt=new Date().toISOString();if(pass==='first'&&previous&&t.firstPassSource==='baseline'){t.firstPassSource='manual-confirmed';t.firstPassManual=true;t.completionHistory=[...(t.completionHistory??[]),{pass:'first',complete:true,changedAt,source:'manual-confirmed',previousCompletedAt:previous}];p.topics[id]=t;await saveProgress(p);return;}const complete=!previous;if(complete){t[key]=changedAt;t[sourceKey]='manual';}else{delete t[key];delete t[sourceKey];}t[manual]=true;t.completionHistory=[...(t.completionHistory??[]),{pass,complete,changedAt,source:'manual',...(previous?{previousCompletedAt:previous}:{})}];p.topics[id]=t;await saveProgress(p);}
  async function toggleRed(id:string){if(!progress)return;const p=structuredClone(progress);p.topics[id]={...(p.topics[id]??{}),redZonePinned:!p.topics[id]?.redZonePinned};await saveProgress(p)}
  async function completeReview(id:string){if(!progress)return;const p=structuredClone(progress),t=p.topics[id]??{};t.shortReviewDates=[...(t.shortReviewDates??[]),today];t.lastPlanReviewAt=new Date().toISOString();p.topics[id]=t;await saveProgress(p)}
  async function saveConfig(){if(!config||!uid)return;const now=new Date().toISOString();config={...config,updatedAt:now,history:[...config.history.slice(-9),{updatedAt:now,summary:'Plan settings updated'}]};await saveStudyPlan(uid,config);notice='Targets recalculated. Existing progress preserved.';}
  async function toggleBuffer(id:string){if(!config)return;config={...config,bufferObjectives:config.bufferObjectives.map(o=>o.id===id?{...o,completedAt:o.completedAt?undefined:new Date().toISOString()}:o)};await saveConfig()}
  function blockCount(block:string,pass:PlanPass){return SURGERY_SYLLABUS.filter(t=>t.block===block&&(pass==='first'?progress?.topics[t.id]?.firstPassCompletedAt:progress?.topics[t.id]?.secondPassCompletedAt)).length}
  function topicPriority(id:string){const p=state.topics[id],plan=progress?.topics[id];return (plan?.redZonePinned?100:0)+(p.gaps.filter(g=>!g.resolvedAt).length*10)+(4-p.mastery);}
  $: remainingTopics=progress&&phase?SURGERY_SYLLABUS.filter(t=>phase.type==='second-pass'?!progress!.topics[t.id]?.secondPassCompletedAt:!progress!.topics[t.id]?.firstPassCompletedAt).sort((a,b)=>topicPriority(b.id)-topicPriority(a.id)):[];
  $: suggested=remainingTopics.slice(0,currentPacing?.todayRemaining??0);
</script>
<svelte:head><title>Study Plan · Trackr</title></svelte:head>
<main class="shell"><button class="back" on:click={()=>goto('/study')}>← Knowledge map</button>
{#if error}<div class="message error">{error}</div>{/if}{#if notice}<div class="message">{notice}</div>{/if}
{#if loading}<section class="card">Loading your plan…</section>{:else if !config||!progress}
  <section class="setup card"><p class="eyebrow">SURGERY · STATE EXAM</p><h1>Build your study plan</h1><p>Trackr found <strong>{candidates.length}</strong> topics with meaningful existing assessment data. Anki repetitions alone are excluded.</p><div class="baseline"><label><input type="checkbox" checked={baseline.size===candidates.length} on:change={(e)=>baseline=(e.currentTarget as HTMLInputElement).checked?new Set(candidates):new Set()}> Select all assessed</label><span>{baseline.size} / 196 selected as first-pass baseline</span></div><div class="candidate-grid">{#each SURGERY_SYLLABUS as topic}<label class:selected={baseline.has(topic.id)}><input type="checkbox" checked={baseline.has(topic.id)} on:change={()=>{const n=new Set(baseline);n.has(topic.id)?n.delete(topic.id):n.add(topic.id);baseline=n}}><b>{topic.id}</b><span>{topic.title}</span></label>{/each}</div><button class="primary" on:click={activate}>Activate plan with this baseline</button></section>
{:else}
  <header><div><p class="eyebrow">SURGERY · STATE EXAM</p><h1>{config.name}</h1><p>{new Date(config.examDate+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})} · {daysLeft} days remaining</p></div><nav><button class:active={tab==='overview'} on:click={()=>tab='overview'}>Overview</button><button class:active={tab==='topics'} on:click={()=>tab='topics'}>Topics</button><button class:active={tab==='edit'} on:click={()=>tab='edit'}>Edit plan</button></nav></header>
  {#if tab==='overview'}
    <section class="hero card"><div><span class="phase">{phase?.name??(today===config.examDate?'Exam day':'Outside plan')}</span><h2>{currentPacing?.status==='ahead'?'Ahead':currentPacing?.status==='behind'?'Behind':'On track'}</h2><p>{currentPacing?.status==='ahead'?`Ahead by ${currentPacing.difference} topics`:currentPacing?.status==='behind'?`Behind by ${currentPacing.difference} topics`:`${currentPacing?.todayRemaining??0} topics remaining today`}</p></div><div class="hero-numbers"><div><span>Required pace</span><strong>{currentPacing?.requiredPace.toFixed(1)??'—'}<small>/day</small></strong></div><div><span>Today</span><strong>{currentPacing?.todayActual??0}<small> / {currentPacing?.todayQuota??0}</small></strong></div><div><span>Projection</span><strong class="date">{projection?.date??'Not enough data'}</strong></div></div></section>
    <section class="passes"><article class="card"><span>First-pass coverage <i title="Topic has been actively studied or assessed.">ⓘ</i></span><strong>{first} / 196</strong><progress max="196" value={first}></progress><small>{196-first} remaining · {Math.round(first/196*100)}%</small></article><article class="card"><span>Second-pass active recall</span><strong>{second} / 196</strong><progress max="196" value={second}></progress><small>{196-second} awaiting review · {Math.round(second/196*100)}%</small></article></section>
    <section class="card"><h3>Progress by question group</h3><p>Coverage, separate from oral mastery.</p><div class="groups">{#each SURGERY_BLOCKS as block}<div><b>{block.label}</b><span>{blockCount(block.id,'first')}/{block.count} first · {blockCount(block.id,'second')}/{block.count} second</span><progress max={block.count} value={blockCount(block.id,phase?.type==='second-pass'?'second':'first')}></progress></div>{/each}</div></section>
    {#if phase?.type==='buffer'}<section class="card buffer"><h3>Buffer / exam mode</h3><p>Weak areas, simulations, propedeutics, radiology and instruments.</p><div class="checklist">{#each config.bufferObjectives.sort((a,b)=>a.order-b.order) as o}<label><input type="checkbox" checked={!!o.completedAt} on:change={()=>toggleBuffer(o.id)}><span>{o.title}</span></label>{/each}</div></section>{:else}
    <section class="today"><article class="card"><span class="eyebrow">TODAY · {today}</span><h3>First-pass topics: {currentPacing?.todayActual??0} / {currentPacing?.todayQuota??0}</h3><p>{topicsAssessedToday} topics assessed · {questionsToday} questions · {currentPacing?.todayRemaining??0} first-pass topics remaining</p><div class="suggestions">{#each suggested as t}<button on:click={()=>goto('/study')}><b>{t.id}</b><span>{t.title}</span></button>{/each}</div></article><article class="card"><span class="eyebrow">SHORT REVIEWS DUE</span><h3>{due.length}</h3>{#each due.slice(0,8) as id}<div class="due"><span><b>{id}</b> {SURGERY_SYLLABUS.find(t=>t.id===id)?.title}</span><button on:click={()=>completeReview(id)}>Done</button></div>{/each}</article></section>
    <section class="card chart"><h3>Planned vs actual</h3><div class="bars">{#each schedule as day}<div title={`${day.date}: target ${day.cumulativeTarget}`}><span style={`height:${Math.max(2,day.cumulativeTarget/196*100)}%`}></span><i style={`height:${Math.max(0,(progress?(phase?.type==='second-pass'?passCount(progress,'second',day.date):passCount(progress,'first',day.date)):0)/196*100)}%`}></i></div>{/each}</div><div class="legend"><span>■ Planned</span><span>■ Actual</span></div></section>{/if}
  {:else if tab==='topics'}<section class="card"><h2>Plan topic state</h2><p>Manual corrections affect coverage only; oral mastery and retention are untouched. Entries labelled “Inferred baseline” still need your confirmation.</p><div class="topic-list">{#each SURGERY_SYLLABUS as t}<div><span><b>{t.id}</b> {t.title}{#if progress.topics[t.id]?.firstPassSource==='baseline'}<small class="inferred">Inferred baseline</small>{/if}</span><button class:done={!!progress.topics[t.id]?.firstPassCompletedAt} on:click={()=>togglePass(t.id,'first')}>{progress.topics[t.id]?.firstPassSource==='baseline'?'Confirm / remove':'First'}</button><button class:done={!!progress.topics[t.id]?.secondPassCompletedAt} on:click={()=>togglePass(t.id,'second')}>Second</button><button class:red={progress.topics[t.id]?.redZonePinned} on:click={()=>toggleRed(t.id)}>●</button></div>{/each}</div></section>
  {:else}<section class="card editor"><h2>Edit study plan</h2><p>Changing targets recalculates the plan. Historical completion timestamps are preserved.</p><label>Plan name<input bind:value={config.name}></label><div class="fields"><label>Plan start<input type="date" bind:value={config.planStartDate}></label><label>Exam date<input type="date" bind:value={config.examDate}></label><label>Forecast window<input type="number" min="2" max="14" bind:value={config.forecastWindowDays}></label></div><h3>Phases</h3>{#each config.phases as p}<div class="phase-edit"><input bind:value={p.name}><select bind:value={p.type}><option value="first-pass">First pass</option><option value="second-pass">Second pass</option><option value="buffer">Buffer</option></select><input type="date" bind:value={p.startDate}><input type="date" bind:value={p.endDate}><input type="number" min="0" max="196" bind:value={p.target}></div>{/each}<h3>Day workload</h3><p>Add weight 0 for off, 0.5 for half, 1 for normal.</p>{#each config.dayOverrides as d}<div class="day-edit"><input type="date" bind:value={d.date}><input type="number" min="0" max="2" step="0.25" bind:value={d.weight}><input placeholder="Note" bind:value={d.note}><button on:click={()=>config={...config!,dayOverrides:config!.dayOverrides.filter(x=>x!==d)}}>Delete</button></div>{/each}<button on:click={()=>config={...config!,dayOverrides:[...config!.dayOverrides,{date:today,weight:0}]}}>Add day override</button><h3>Buffer objectives</h3>{#each config.bufferObjectives.sort((a,b)=>a.order-b.order) as o}<div class="day-edit"><input bind:value={o.title}><input placeholder="Notes" bind:value={o.notes}><button on:click={()=>config={...config!,bufferObjectives:config!.bufferObjectives.filter(x=>x.id!==o.id)}}>Delete</button></div>{/each}<button on:click={()=>config={...config!,bufferObjectives:[...config!.bufferObjectives,{id:crypto.randomUUID(),title:'New objective',order:config!.bufferObjectives.length}]}}>Add objective</button><button class="primary save" on:click={saveConfig}>Save & recalculate</button></section>{/if}
{/if}</main>
<style>
 :global(body){background:#090c12;color:#eef0f8}.shell{max-width:1500px;margin:auto;padding:48px 28px 120px}.back{background:none;border:0;color:#8d98ff;font-size:16px;margin-bottom:28px}header{display:flex;justify-content:space-between;align-items:end;margin-bottom:24px}h1{font-size:clamp(38px,6vw,72px);line-height:.95;margin:8px 0}h2{font-size:36px;margin:8px 0}h3{margin:5px 0 12px}.eyebrow{letter-spacing:.18em;color:#969eb4;font-size:12px;font-weight:800}.card{background:linear-gradient(145deg,#181d27,#121720);border:1px solid #2a3140;border-radius:22px;padding:24px}.message{padding:12px 18px;border-radius:12px;background:#193229;margin-bottom:18px}.error{background:#4b222a}nav{display:flex;gap:8px}button{border:1px solid #353d4d;background:#202632;color:#e9ebf3;border-radius:11px;padding:10px 14px;font:inherit;cursor:pointer}button.active,.primary,button.done{background:#7385ff;color:#090c12;border-color:#7385ff;font-weight:700}.hero{display:flex;justify-content:space-between;gap:28px;align-items:center;margin-bottom:14px}.phase{color:#aab1c4}.hero-numbers{display:flex;gap:42px}.hero-numbers div{display:flex;flex-direction:column}.hero-numbers span,.passes article>span{color:#969eb4}.hero-numbers strong{font-size:30px}.hero-numbers small{font-size:14px}.hero-numbers .date{font-size:17px;margin-top:9px}.passes,.today{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px}.passes strong{display:block;font-size:34px;margin:10px 0}progress{width:100%;height:8px;accent-color:#7c72ff}.passes small{display:block;color:#969eb4;margin-top:8px}.groups{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.groups div{display:grid;gap:8px}.groups span{font-size:13px;color:#969eb4}.today,.buffer{margin-top:14px}.suggestions{display:grid;gap:6px;max-height:310px;overflow:auto}.suggestions button{text-align:left;display:flex;gap:10px}.due{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #2a3140;padding:8px 0;font-size:13px}.chart{margin-top:14px}.bars{height:190px;display:flex;align-items:end;gap:5px;border-bottom:1px solid #394052}.bars div{height:100%;flex:1;position:relative;display:flex;align-items:end;gap:1px}.bars span,.bars i{display:block;width:50%;background:#3c4762;border-radius:3px 3px 0 0}.bars i{background:#7b75ff}.legend{display:flex;gap:20px;color:#969eb4;margin-top:8px}.checklist{columns:2}.checklist label{display:block;padding:8px}.candidate-grid{display:grid;grid-template-columns:repeat(3,1fr);max-height:480px;overflow:auto;gap:6px;margin:16px 0}.candidate-grid label{display:flex;gap:8px;padding:8px;border:1px solid #292f3c;border-radius:9px}.candidate-grid label.selected{border-color:#7180ff}.candidate-grid span{font-size:12px}.baseline{display:flex;justify-content:space-between}.topic-list>div{display:grid;grid-template-columns:1fr auto auto auto;gap:7px;align-items:center;padding:7px;border-bottom:1px solid #262c38}.topic-list button{padding:6px 10px}.topic-list button.red{color:#ff5d77}.editor>label,.editor label{display:grid;gap:6px;color:#aeb5c7}.fields,.phase-edit,.day-edit{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:8px 0}.phase-edit{grid-template-columns:2fr 1fr 1fr 1fr .5fr}input,select{background:#0d1118;border:1px solid #353d4d;color:#eef0f8;border-radius:9px;padding:10px;font:inherit}.editor h3{margin-top:28px}.save{display:block;margin-top:28px}
 @media(max-width:800px){.shell{padding:24px 14px 100px}header,.hero{align-items:stretch;flex-direction:column}nav{overflow:auto}.hero-numbers{display:grid;grid-template-columns:1fr 1fr;gap:12px}.passes,.today,.groups{grid-template-columns:1fr}.candidate-grid{grid-template-columns:1fr}.checklist{columns:1}.phase-edit,.day-edit,.fields{grid-template-columns:1fr}.topic-list>div{grid-template-columns:1fr auto auto auto}.topic-list span{font-size:12px}}
  .inferred{display:block;color:#d7b96d;font-size:.65rem;margin-top:3px}
</style>
